CREATE OR REPLACE FUNCTION public.student_financial_status(_student_id uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.plans;s public.students;c public.charges;t date:=public.today_br();soon int;autos boolean; BEGIN IF auth.role() IN ('anon','authenticated') AND NOT public.can_access_student(_student_id) THEN RAISE EXCEPTION 'Acesso negado';END IF;SELECT * INTO s FROM public.students WHERE id=_student_id;IF NOT FOUND THEN RETURN 'inativo';END IF;IF s.manual_block THEN RETURN 'bloqueado';END IF;SELECT * INTO p FROM public.plans WHERE student_id=_student_id;IF NOT FOUND OR NOT p.active OR (p.end_date IS NOT NULL AND p.end_date<t) THEN RETURN 'inativo';END IF;SELECT * INTO c FROM public.charges WHERE student_id=_student_id AND status='aberta' ORDER BY due_date LIMIT 1;IF NOT FOUND THEN RETURN 'em_dia';END IF;SELECT due_soon_days,auto_suspend INTO soon,autos FROM public.trainer_settings WHERE trainer_id=s.trainer_id;IF coalesce(autos,true) AND t>c.due_date+p.grace_days THEN RETURN 'bloqueado';END IF;IF t>c.due_date THEN RETURN 'atrasado';END IF;IF t=c.due_date THEN RETURN 'pendente';END IF;IF c.due_date-t<=coalesce(soon,5) THEN RETURN 'proximo';END IF;RETURN 'em_dia';END $$;
REVOKE ALL ON FUNCTION public.student_financial_status(uuid),public.student_has_access(uuid),public.can_access_student(uuid),public.my_access_status(),public.my_student_id(),public.get_my_payment_instructions(),public.trainer_students_overview() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.student_financial_status(uuid),public.student_has_access(uuid),public.can_access_student(uuid),public.my_access_status(),public.my_student_id(),public.get_my_payment_instructions(),public.trainer_students_overview() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.review_workout_version(_version_id uuid,_action text,_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.workout_versions;u uuid;BEGIN SELECT * INTO v FROM public.workout_versions WHERE id=_version_id FOR UPDATE;IF NOT FOUND OR NOT public.is_trainer_of(v.student_id) THEN RAISE EXCEPTION 'Acesso negado';END IF;IF v.status NOT IN ('pendente','ajustes') THEN RAISE EXCEPTION 'Esta versão não está aguardando revisão';END IF;IF _action NOT IN ('aprovar','ajustes','reprovar') THEN RAISE EXCEPTION 'Ação inválida';END IF;IF _action IN ('ajustes','reprovar') AND length(trim(coalesce(_notes,'')))=0 THEN RAISE EXCEPTION 'Informe o motivo';END IF;IF _action='aprovar' AND (NOT EXISTS(SELECT 1 FROM public.workout_exercises WHERE version_id=v.id) OR EXISTS(SELECT 1 FROM public.workout_sessions s WHERE s.version_id=v.id AND NOT EXISTS(SELECT 1 FROM public.workout_exercises e WHERE e.session_id=s.id))) THEN RAISE EXCEPTION 'Preencha os exercícios de todas as sessões';END IF;SELECT user_id INTO u FROM public.students WHERE id=v.student_id;IF _action='aprovar' THEN UPDATE public.workout_versions SET status='substituido' WHERE student_id=v.student_id AND status='aprovado' AND id<>v.id;UPDATE public.workout_versions SET status='aprovado',reviewed_by=auth.uid(),reviewed_at=now(),review_notes=_notes,published_at=now() WHERE id=v.id;PERFORM public.notify(u,'Novo treino disponível','Seu treino foi aprovado pelo personal.','/aluno/treino',NULL);ELSE UPDATE public.workout_versions SET status=CASE WHEN _action='ajustes' THEN 'ajustes'::public.workout_status ELSE 'reprovado'::public.workout_status END,reviewed_by=auth.uid(),reviewed_at=now(),review_notes=_notes WHERE id=v.id;END IF;INSERT INTO public.workout_reviews(version_id,action,notes,reviewer_id) VALUES(v.id,_action,_notes,auth.uid());PERFORM public.log_audit(v.student_id,'treino_'||_action,'workout_versions',v.id,jsonb_build_object('observacoes',_notes));END $$;
CREATE OR REPLACE FUNCTION public.manage_student_profile(_student_id uuid,_name text,_phone text,_birth date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_trainer_of(_student_id) AND NOT public.is_own_student(_student_id) THEN RAISE EXCEPTION 'Acesso negado';END IF;IF length(trim(_name)) NOT BETWEEN 1 AND 150 OR length(_phone)>30 OR _birth>public.today_br() THEN RAISE EXCEPTION 'Dados pessoais inválidos';END IF;UPDATE public.profiles SET full_name=trim(_name),phone=_phone,birth_date=_birth WHERE id=(SELECT user_id FROM public.students WHERE id=_student_id);END $$;
REVOKE ALL ON FUNCTION public.manage_student_profile(uuid,text,text,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.manage_student_profile(uuid,text,text,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.public_team_contact() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('phone',contact_phone,'cta',public_cta,'invite_code',invite_code) FROM public.trainer_settings WHERE public.has_role(trainer_id,'admin') ORDER BY created_at LIMIT 1 $$;
GRANT EXECUTE ON FUNCTION public.public_team_contact() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.restricted_student_access(_student_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_trainer_of(_student_id) OR (public.is_own_student(_student_id) AND public.student_financial_status(_student_id)<>'bloqueado') $$;
ALTER POLICY "student manages own assessment" ON public.assessments USING(public.is_own_student(student_id) AND public.restricted_student_access(student_id)) WITH CHECK(public.is_own_student(student_id) AND public.restricted_student_access(student_id));
ALTER POLICY "read training" ON public.training_sessions USING(public.is_trainer_of(student_id) OR (public.is_own_student(student_id) AND public.student_has_access(student_id)));
ALTER POLICY "read logs" ON public.exercise_logs USING(public.is_trainer_of(student_id) OR (public.is_own_student(student_id) AND public.student_has_access(student_id)));
ALTER POLICY "read photos" ON public.body_photos USING((public.is_own_student(student_id) AND public.restricted_student_access(student_id)) OR (public.is_trainer_of(student_id) AND public.has_photo_consent(student_id)));
CREATE OR REPLACE FUNCTION public.relationship_daily_notifications() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;elapsed integer;BEGIN
FOR r IN SELECT s.id,s.trainer_id,s.user_id,s.created_at,p.full_name,p.birth_date,t.attention_days,t.priority_days,a.available_days,a.submitted_at,(SELECT max(performed_on) FROM public.training_sessions WHERE student_id=s.id AND finished_at IS NOT NULL) last_training FROM public.students s JOIN public.profiles p ON p.id=s.user_id JOIN public.trainer_settings t ON t.trainer_id=s.trainer_id LEFT JOIN public.assessments a ON a.student_id=s.id LOOP
IF to_char(r.birth_date,'MM-DD')=to_char(public.today_br(),'MM-DD') THEN PERFORM public.notify(r.trainer_id,'Aniversariante do dia',r.full_name,'/admin/alunos/'||r.id,'birthday_'||r.id||'_'||extract(year FROM public.today_br()));END IF;
elapsed:=public.today_br()-coalesce(r.last_training,r.submitted_at::date);
IF elapsed>=r.attention_days AND r.submitted_at IS NOT NULL THEN PERFORM public.notify(r.trainer_id,'Acompanhamento de treino',r.full_name||' está sem registrar treinos. Confira a frequência planejada.','/admin/alunos/'||r.id,'inactivity_'||r.id||'_'||public.today_br());END IF;
END LOOP;
FOR r IN SELECT id,trainer_id,name FROM public.crm_leads WHERE next_contact_on<=public.today_br() AND status NOT IN ('matriculado','nao_convertido') LOOP PERFORM public.notify(r.trainer_id,'Acompanhar interessado',r.name,'/admin/crm','lead_followup_'||r.id||'_'||public.today_br());END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.relationship_daily_notifications() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.relationship_daily_notifications() TO service_role;